CREATE TABLE carrier_award_configs(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),company_id uuid NOT NULL REFERENCES companies(id) ON DELETE CASCADE,name text NOT NULL,performance_weight numeric(6,3) NOT NULL DEFAULT 35,cost_weight numeric(6,3) NOT NULL DEFAULT 25,speed_weight numeric(6,3) NOT NULL DEFAULT 20,reliability_weight numeric(6,3) NOT NULL DEFAULT 10,compliance_weight numeric(6,3) NOT NULL DEFAULT 10,active boolean NOT NULL DEFAULT true,created_at timestamptz NOT NULL DEFAULT now(),created_by uuid REFERENCES users(id),UNIQUE(company_id,name),CHECK(performance_weight+cost_weight+speed_weight+reliability_weight+compliance_weight=100));
ALTER TABLE order_carrier_assignments ADD COLUMN recommended_carrier_service_id uuid,ADD COLUMN selected_rank integer CHECK(selected_rank>0),ADD COLUMN award_score numeric(7,3),ADD COLUMN award_snapshot jsonb,ADD CONSTRAINT order_carrier_assignment_recommended_fk FOREIGN KEY(company_id,recommended_carrier_service_id) REFERENCES carrier_services(company_id,id);
CREATE VIEW carrier_award_recommendations WITH(security_invoker=true) AS WITH candidates AS(SELECT o.company_id,o.id order_id,o.order_no,o.warehouse_id,o.store_id,c.id carrier_service_id,c.name carrier_name,c.service_level,c.transit_days,c.cutoff_time,coalesce(r.carrier_service_id=c.id,false) route_preferred,coalesce(sc.score,50) performance_score,greatest(0,100-coalesce(sc.failure_rate,10)*5) reliability_score,coalesce(rc.base_charge+rc.per_kg_charge,0) estimated_cost,ct.id contract_id,ct.effective_to contract_end,coalesce(rem.open_cases,0) open_remediations,coalesce(rem.critical_cases,0) critical_remediations,cfg.performance_weight,cfg.cost_weight,cfg.speed_weight,cfg.reliability_weight,cfg.compliance_weight FROM sales_orders o JOIN carrier_services c ON c.company_id=o.company_id AND c.active LEFT JOIN store_delivery_routes r ON r.company_id=o.company_id AND r.store_id=o.store_id AND r.warehouse_id=o.warehouse_id AND r.active LEFT JOIN LATERAL(SELECT score,failure_rate FROM carrier_performance_scorecards s WHERE s.company_id=o.company_id AND s.carrier_service_id=c.id AND s.warehouse_id=o.warehouse_id ORDER BY period DESC LIMIT 1)sc ON true LEFT JOIN LATERAL(SELECT base_charge,per_kg_charge FROM carrier_rate_cards x WHERE x.company_id=o.company_id AND x.carrier_service_id=c.id AND x.active AND x.effective_from<=current_date AND(x.effective_to IS NULL OR x.effective_to>=current_date) ORDER BY x.effective_from DESC,x.version DESC LIMIT 1)rc ON true LEFT JOIN LATERAL(SELECT id,effective_to FROM carrier_contracts x WHERE x.company_id=o.company_id AND x.carrier_service_id=c.id AND x.status='active' AND current_date BETWEEN x.effective_from AND x.effective_to ORDER BY x.effective_to DESC LIMIT 1)ct ON true LEFT JOIN LATERAL(SELECT count(*)FILTER(WHERE status NOT IN('verified','cancelled')) open_cases,count(*)FILTER(WHERE severity='critical' AND status NOT IN('verified','cancelled')) critical_cases FROM carrier_sla_remediation_cases x WHERE x.company_id=o.company_id AND x.carrier_service_id=c.id AND x.warehouse_id=o.warehouse_id)rem ON true JOIN LATERAL(SELECT * FROM carrier_award_configs x WHERE x.company_id=o.company_id AND x.active ORDER BY x.created_at DESC LIMIT 1)cfg ON true WHERE o.status='packed'),normalized AS(SELECT x.*,CASE WHEN estimated_cost=0 THEN 40 ELSE 100*min(NULLIF(estimated_cost,0))OVER(PARTITION BY company_id,order_id)/estimated_cost END cost_score,100.0*min(transit_days+1)OVER(PARTITION BY company_id,order_id)/(transit_days+1) speed_score,greatest(0,100-(contract_id IS NULL)::int*35-coalesce((contract_end<current_date+30)::int,0)*15-least(open_remediations*10,30)-critical_remediations*25) compliance_score FROM candidates x),scored AS(SELECT x.*,least(100,greatest(0,performance_score*performance_weight/100+cost_score*cost_weight/100+speed_score*speed_weight/100+reliability_score*reliability_weight/100+compliance_score*compliance_weight/100+(route_preferred::int*5))) award_score,concat_ws('; ',CASE WHEN NOT route_preferred THEN 'not preferred for Store route' END,CASE WHEN contract_id IS NULL THEN 'no active contract' END,CASE WHEN contract_end<current_date+30 THEN 'contract expires within 30 days' END,CASE WHEN open_remediations>0 THEN open_remediations||' open remediation case(s)' END,CASE WHEN critical_remediations>0 THEN critical_remediations||' critical remediation case(s)' END,CASE WHEN estimated_cost=0 THEN 'no current rate card' END) warnings FROM normalized x) SELECT x.*,row_number()OVER(PARTITION BY company_id,order_id ORDER BY award_score DESC,route_preferred DESC,transit_days,carrier_name,service_level) recommendation_rank,CASE WHEN localtime<cutoff_time THEN current_date+cutoff_time ELSE current_date+1+cutoff_time END promised_dispatch_at,(CASE WHEN localtime<cutoff_time THEN current_date+cutoff_time ELSE current_date+1+cutoff_time END)+make_interval(days=>transit_days) expected_delivery_at FROM scored x;
ALTER TABLE carrier_award_configs ENABLE ROW LEVEL SECURITY;ALTER TABLE carrier_award_configs FORCE ROW LEVEL SECURITY;CREATE POLICY tenant_carrier_award_configs ON carrier_award_configs USING(company_id=nullif(current_setting('app.company_id',true),'')::uuid) WITH CHECK(company_id=nullif(current_setting('app.company_id',true),'')::uuid);GRANT SELECT,INSERT,UPDATE,DELETE ON carrier_award_configs TO stockflow_app;GRANT SELECT ON carrier_award_recommendations TO stockflow_app;CREATE INDEX carrier_award_config_active_idx ON carrier_award_configs(company_id,active,created_at DESC);
INSERT INTO carrier_award_configs(company_id,name,created_by) SELECT c.id,'Default carrier award weights',m.user_id FROM companies c JOIN LATERAL(SELECT user_id FROM company_members WHERE company_id=c.id AND role='owner' ORDER BY user_id LIMIT 1)m ON true ON CONFLICT DO NOTHING;
